CREATE TABLE app_users (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) UNIQUE NOT NULL, display_name VARCHAR(100) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE loans (id VARCHAR(36) PRIMARY KEY, borrower_id VARCHAR(36) NOT NULL REFERENCES app_users(id), applicant_name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, city VARCHAR(100) NOT NULL, employment VARCHAR(30) NOT NULL, purpose VARCHAR(30) NOT NULL, property_address VARCHAR(500) NOT NULL, co_applicant VARCHAR(100), income NUMERIC(18,2) NOT NULL, co_income NUMERIC(18,2) NOT NULL, obligations NUMERIC(18,2) NOT NULL, property_value NUMERIC(18,2) NOT NULL, requested_amount NUMERIC(18,2) NOT NULL, sanctioned_amount NUMERIC(18,2) NOT NULL, annual_rate NUMERIC(7,4) NOT NULL, tenure_months INTEGER NOT NULL, stage VARCHAR(40) NOT NULL, credit_checked BOOLEAN NOT NULL, legal_checked BOOLEAN NOT NULL, valuation_checked BOOLEAN NOT NULL, sanction_accepted BOOLEAN NOT NULL, disbursed NUMERIC(18,2) NOT NULL, outstanding NUMERIC(18,2) NOT NULL, emi NUMERIC(18,2) NOT NULL, remaining_months INTEGER NOT NULL, paid_interest NUMERIC(18,2) NOT NULL, paid_principal NUMERIC(18,2) NOT NULL, due_date VARCHAR(10), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, revision BIGINT NOT NULL);
CREATE INDEX idx_loans_borrower ON loans(borrower_id);
CREATE TABLE loan_documents (id VARCHAR(36) PRIMARY KEY, loan_id VARCHAR(36) NOT NULL REFERENCES loans(id), kind VARCHAR(50) NOT NULL, filename VARCHAR(150) NOT NULL, content_type VARCHAR(50) NOT NULL, storage_key VARCHAR(36) NOT NULL, verified BOOLEAN NOT NULL, uploaded_at VARCHAR(40) NOT NULL);
CREATE INDEX idx_documents_loan ON loan_documents(loan_id);
CREATE TABLE loan_events (id VARCHAR(36) PRIMARY KEY, loan_id VARCHAR(36) NOT NULL REFERENCES loans(id), actor_id VARCHAR(36) NOT NULL REFERENCES app_users(id), message VARCHAR(1200) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX idx_events_loan ON loan_events(loan_id,created_at);
CREATE TABLE loan_queries (id VARCHAR(36) PRIMARY KEY, loan_id VARCHAR(36) NOT NULL REFERENCES loans(id), question VARCHAR(1000) NOT NULL, response VARCHAR(1000), resolved BOOLEAN NOT NULL);
CREATE INDEX idx_queries_loan ON loan_queries(loan_id);
CREATE TABLE loan_payments (id VARCHAR(36) PRIMARY KEY, loan_id VARCHAR(36) NOT NULL REFERENCES loans(id), amount NUMERIC(18,2) NOT NULL, kind VARCHAR(20) NOT NULL, mode VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, reference VARCHAR(100), idempotency_key VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL, confirmed_at VARCHAR(40), UNIQUE(loan_id,idempotency_key));
CREATE INDEX idx_payments_loan ON loan_payments(loan_id,created_at);
